var p=UnityEngine.Object.FindFirstObjectByType<CurtainCall.ItemArt.ItemGameplayPlayground>();
var mover=p.Player.GetComponent<CurtainCall.Player.PlayerMover>();var actor=p.Player.GetComponent<CurtainCall.Player.HumanoidPlayerPresentation>();var carry=CurtainCall.WaitingRoom.PropCarry.Instance;
var original=UnityEngine.InputSystem.InputSystem.settings;var working=UnityEngine.Object.Instantiate(original);working.hideFlags=UnityEngine.HideFlags.DontSave;UnityEngine.InputSystem.InputSystem.settings=working;working.backgroundBehavior=UnityEngine.InputSystem.InputSettings.BackgroundBehavior.IgnoreFocus;working.editorInputBehaviorInPlayMode=UnityEngine.InputSystem.InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
var previous=UnityEngine.InputSystem.Keyboard.current;var keyboard=UnityEngine.InputSystem.InputSystem.AddDevice<UnityEngine.InputSystem.Keyboard>("KeyHairpinReview");keyboard.MakeCurrent();
var records=new System.Collections.Generic.List<object>();var failures=new System.Collections.Generic.List<string>();
var steps=new System.Collections.Generic.List<System.Action>();int step=0;double next=UnityEditor.EditorApplication.timeSinceStartup;string[] slots=null;
System.Action<bool> press=down=>UnityEngine.InputSystem.InputSystem.QueueStateEvent(keyboard,down?new UnityEngine.InputSystem.LowLevel.KeyboardState(UnityEngine.InputSystem.Key.F):new UnityEngine.InputSystem.LowLevel.KeyboardState());
System.Action<string,bool> check=(name,pass)=>{records.Add(new{name,pass,frame=UnityEngine.Time.frameCount,message=CurtainCall.WaitingRoom.ExplorationState.Instance.LastMessage});if(!pass)failures.Add(name);};
steps.Add(()=>{p.Player.GetComponent<CurtainCall.Player.PlayerCondition>().SetLostParts(CurtainCall.Player.PlayerCondition.PartsForLostCount(0));p.Player.GetComponent<CurtainCall.Player.PlayerModelSlot>().SetModel(p.CharacterPrefabs[0]);press(false);slots=carry.Held(0).Select(x=>x.Uid+":"+x.ItemId).ToArray();mover.SetStartPose(new UnityEngine.Vector3(-4,.05f,-4.8f),UnityEngine.Quaternion.identity);});
steps.Add(()=>{check("key pickup focus",object.ReferenceEquals(CurtainCall.WaitingRoom.ShopReach.Focused,p.KeyPickup.GetComponent<CurtainCall.WaitingRoom.ExplorationGate>()));press(true);});steps.Add(()=>press(false));
steps.Add(()=>{check("shared key acquired",p.KeyPickup.GetComponent<CurtainCall.WaitingRoom.ExplorationGate>().Opened);check("slots unchanged",slots.SequenceEqual(carry.Held(0).Select(x=>x.Uid+":"+x.ItemId)));check("world key hidden",!UnityEngine.Object.FindObjectsByType<UnityEngine.Transform>(UnityEngine.FindObjectsSortMode.None).Any(t=>t.name.StartsWith("Key artwork / ")&&t.gameObject.activeInHierarchy));mover.SetStartPose(new UnityEngine.Vector3(-1,.05f,-4.9f),UnityEngine.Quaternion.identity);});
steps.Add(()=>{check("key door focus",object.ReferenceEquals(CurtainCall.WaitingRoom.ShopReach.Focused,p.KeyDoor.GetComponent<CurtainCall.WaitingRoom.ExplorationGate>()));press(true);});steps.Add(()=>press(false));
steps.Add(()=>{check("key door opened",p.KeyDoor.GetComponent<CurtainCall.WaitingRoom.ExplorationGate>().Opened);check("key visible during use",actor.HeldItemVisual!=null&&actor.HeldItemVisual.name=="RightHand_route-key"&&actor.ItemMotion=="ItemManipulate");check("key use keeps slots",slots.SequenceEqual(carry.Held(0).Select(x=>x.Uid+":"+x.ItemId)));p.Give("magician-hairpin");mover.SetStartPose(new UnityEngine.Vector3(.35f,.05f,.5f),UnityEngine.Quaternion.identity);});
for(int i=0;i<3;i++){steps.Add(()=>press(true));steps.Add(()=>press(false));steps.Add(()=>{});steps.Add(()=>{});}
steps.Add(()=>{var target=p.Stations[1].GetComponent<CurtainCall.WaitingRoom.ToolTarget>();check("hairpin chest opened",CurtainCall.WaitingRoom.ExplorationState.Instance.IsOpen(target.TargetId));check("hairpin consumed once",carry.Held(0).Any(x=>x.ItemId=="magician-hairpin"&&x.Uses==4));check("hairpin held",actor.HeldItemVisual!=null&&actor.HeldItemVisual.name=="RightHand_magician-hairpin");});
UnityEditor.EditorApplication.CallbackFunction tick=null;
System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;UnityEngine.InputSystem.InputSystem.RemoveDevice(keyboard);UnityEngine.InputSystem.InputSystem.settings=original;UnityEngine.Object.DestroyImmediate(working);previous?.MakeCurrent();System.IO.File.WriteAllText("Tasks/Active/Task-20261101-088-item-art-interaction/Art/key-hairpin-validation.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{records,failures},Newtonsoft.Json.Formatting.Indented));};
tick=()=>{if(!UnityEditor.EditorApplication.isPlaying){failures.Add("Play stopped");finish();return;}if(UnityEditor.EditorApplication.timeSinceStartup<next)return;try{if(step==steps.Count){finish();return;}steps[step++]();next=UnityEditor.EditorApplication.timeSinceStartup+.4;}catch(System.Exception e){failures.Add(e.ToString());finish();}};
UnityEditor.EditorApplication.update+=tick;return "Key pickup, key door, and hairpin F-input validation started.";

